module uart_core (
  input                  clk_i,
  input                  rst_ni,

  input  uart_reg_pkg::uart_reg2hw_t reg2hw,
  output uart_reg_pkg::uart_hw2reg_t hw2reg,

  input                  rx,
  output logic           tx,

  output logic           lsio_trigger_o,

  output logic           intr_tx_watermark_o,
  output logic           intr_tx_empty_o,
  output logic           intr_rx_watermark_o,
  output logic           intr_tx_done_o,
  output logic           intr_rx_overflow_o,
  output logic           intr_rx_frame_err_o,
  output logic           intr_rx_break_err_o,
  output logic           intr_rx_timeout_o,
  output logic           intr_rx_parity_err_o
);

  import uart_reg_pkg::*;

  localparam int NcoWidth = $bits(reg2hw.ctrl.nco.q);
  localparam int TxFifoDepthW = $clog2(TxFifoDepth)+1;
  localparam int RxFifoDepthW = $clog2(RxFifoDepth)+1;

  // The design does not support FIFOs deeper than 255 elements with the current CSR layout.
  `ASSERT_INIT(TxFifoDepth_A, TxFifoDepth < 256)
  `ASSERT_INIT(RxFifoDepth_A, RxFifoDepth < 256)

  logic   [15:0]  rx_val_q;
  logic   [7:0]   uart_rdata;
  logic           tick_baud_x16, rx_tick_baud;

  logic   [TxFifoDepthW-1:0] tx_fifo_depth;
  logic   [RxFifoDepthW-1:0] rx_fifo_depth;
  logic   [RxFifoDepthW-1:0] rx_fifo_depth_prev_q;

  logic   [23:0]  rx_timeout_count_d, rx_timeout_count_q, uart_rxto_val;
  logic           rx_fifo_depth_changed, uart_rxto_en;
  logic           tx_enable, rx_enable;
  logic           sys_loopback, line_loopback, rxnf_enable;
  logic           uart_fifo_rxrst, uart_fifo_txrst;
  logic   [2:0]   uart_fifo_rxilvl;
  logic   [2:0]   uart_fifo_txilvl;
  logic           ovrd_tx_en, ovrd_tx_val;
  logic   [7:0]   tx_fifo_data;
  logic           tx_fifo_rready, tx_fifo_rvalid;
  logic           tx_fifo_wready, tx_uart_idle;
  logic           tx_out;
  logic           tx_out_q;
  logic   [7:0]   rx_fifo_data;
  logic           rx_valid, rx_fifo_wvalid, rx_fifo_rvalid;
  logic           rx_fifo_wready, rx_uart_idle;
  logic           rx_sync;
  logic           rx_in;
  logic           break_err;
  logic   [4:0]   allzero_cnt_d, allzero_cnt_q;
  logic           allzero_err, not_allzero_char;
  logic           event_tx_watermark, event_tx_empty, event_rx_watermark, event_tx_done;
  logic           event_rx_overflow, event_rx_frame_err, event_rx_break_err, event_rx_timeout;
  logic           event_rx_parity_err;
  logic           tx_uart_idle_q;

  assign tx_enable        = reg2hw.ctrl.tx.q;
  assign rx_enable        = reg2hw.ctrl.rx.q;
  assign rxnf_enable      = reg2hw.ctrl.nf.q;
  assign sys_loopback     = reg2hw.ctrl.slpbk.q;
  assign line_loopback    = reg2hw.ctrl.llpbk.q;

  assign uart_fifo_rxrst  = reg2hw.fifo_ctrl.rxrst.q & reg2hw.fifo_ctrl.rxrst.qe;
  assign uart_fifo_txrst  = reg2hw.fifo_ctrl.txrst.q & reg2hw.fifo_ctrl.txrst.qe;
  assign uart_fifo_rxilvl = reg2hw.fifo_ctrl.rxilvl.q;
  assign uart_fifo_txilvl = reg2hw.fifo_ctrl.txilvl.q;

  assign ovrd_tx_en       = reg2hw.ovrd.txen.q;
  assign ovrd_tx_val      = reg2hw.ovrd.txval.q;

  typedef enum logic {
    BRK_CHK,
    BRK_WAIT
  } break_st_e ;

  break_st_e break_st_q;

  assign not_allzero_char = rx_valid & (~event_rx_frame_err | (rx_fifo_data != 8'h0));
  assign allzero_err = event_rx_frame_err & (rx_fifo_data == 8'h0);


  assign allzero_cnt_d = (break_st_q == BRK_WAIT || not_allzero_char) ? 5'h0 :
                          //allzero_cnt_q[4] never be 1b without break_st_q as BRK_WAIT
                          //allzero_cnt_q[4] ? allzero_cnt_q :
                          allzero_err ? allzero_cnt_q + 5'd1 :
                          allzero_cnt_q;

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni)        allzero_cnt_q <= '0;
  else if (rx_enable) allzero_cnt_q <= allzero_cnt_d;
end

always_comb begin
  unique case (reg2hw.ctrl.rxblvl.q)
    2'h0:    break_err = allzero_cnt_d >= 5'd2;
    2'h1:    break_err = allzero_cnt_d >= 5'd4;
    2'h2:    break_err = allzero_cnt_d >= 5'd8;
    default: break_err = allzero_cnt_d >= 5'd16;
  endcase
end

assign hw2reg.val.d  = rx_val_q;

assign hw2reg.rdata.d = uart_rdata;

assign hw2reg.status.rxempty.d     = ~rx_fifo_rvalid;
assign hw2reg.status.rxidle.d      = rx_uart_idle;
assign hw2reg.status.txidle.d      = tx_uart_idle & ~tx_fifo_rvalid;
assign hw2reg.status.txempty.d     = ~tx_fifo_rvalid;
assign hw2reg.status.rxfull.d      = ~rx_fifo_wready;
assign hw2reg.status.txfull.d      = ~tx_fifo_wready;

assign hw2reg.fifo_status.txlvl.d  = 8'(tx_fifo_depth);
assign hw2reg.fifo_status.rxlvl.d  = 8'(rx_fifo_depth);

// resets are self-clearing, so need to update FIFO_CTRL
assign hw2reg.fifo_ctrl.rxilvl.de = 1'b0;
assign hw2reg.fifo_ctrl.rxilvl.d  = 3'h0;
assign hw2reg.fifo_ctrl.txilvl.de = 1'b0;
assign hw2reg.fifo_ctrl.txilvl.d  = 3'h0;

//              NCO 16x Baud Generator
// output clock rate is:
//      Fin * (NCO/2**NcoWidth)
logic   [NcoWidth:0]     nco_sum_q; // extra bit to get the carry

assign tick_baud_x16 = nco_sum_q[16];

//////////////
// TX Logic //
//////////////

assign tx_fifo_rready = tx_uart_idle & tx_fifo_rvalid & tx_enable;

prim_fifo_sync #(
  .Width   (8),
  .Pass    (1'b0),
  .Depth   (TxFifoDepth)
) u_uart_txfifo (
  .clk_i,
  .rst_ni,
  .clr_i   (uart_fifo_txrst),
  .wvalid_i(reg2hw.wdata.qe),
  .wready_o(tx_fifo_wready),
  .wdata_i (reg2hw.wdata.q),
  .depth_o (tx_fifo_depth),
  .full_o (),
  .rvalid_o(tx_fifo_rvalid),
  .rready_i(tx_fifo_rready),
  .rdata_o (tx_fifo_data),
  .err_o   ()
);

uart_tx uart_tx (
  .clk_i,
  .rst_ni,
  .tx_enable,
  .tick_baud_x16,
  .parity_enable  (reg2hw.ctrl.parity_en.q),
  .wr             (tx_fifo_rready),
  .wr_parity      ((^tx_fifo_data) ^ reg2hw.ctrl.parity_odd.q),
  .wr_data        (tx_fifo_data),
  .idle           (tx_uart_idle),
  .tx             (tx_out)
);

assign tx = line_loopback ? rx : tx_out_q ;

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    tx_out_q <= 1'b1;
  end else if (ovrd_tx_en) begin
    tx_out_q <= ovrd_tx_val ;
  end else if (sys_loopback) begin
    tx_out_q <= 1'b1;
  end else begin
    tx_out_q <= tx_out;
  end
end

prim_flop_2sync #(
  .Width(1),
  .ResetValue(1'b1)
) sync_rx (
  .clk_i,
  .rst_ni,
  .d_i(rx),
  .q_o(rx_sync)
);

// Based on: en.wikipedia.org/wiki/Repetition_code mentions the use of a majority filter
// in UART to ignore brief noise spikes
logic   rx_sync_q1, rx_sync_q2, rx_in_mx, rx_in_maj;

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    rx_sync_q1 <= 1'b1;
    rx_sync_q2 <= 1'b1;
  end else begin
    rx_sync_q1 <= rx_sync;
    rx_sync_q2 <= rx_sync_q1;
  end
end

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni)            rx_val_q <= 16'h0;
  else if (tick_baud_x16) rx_val_q <= {rx_val_q[14:0], rx_in};
end

always_comb begin
  // Create power of two thresholds.
  // The threshold saturates at half the FIFO depth.
  if (uart_fifo_txilvl >= (TxFifoDepthW-2)) begin
    tx_watermark_thresh = TxFifoDepthW'(TxFifoDepth/2);
  end else begin
    tx_watermark_thresh = 1'b1 << uart_fifo_txilvl;
  end
  event_tx_watermark = tx_fifo_depth < tx_watermark_thresh;
end

always_comb begin
  unique case (uart_fifo_rxilvl)
    default: begin
      if (uart_fifo_rxilvl > RxFifoDepthW - 1) begin
        rx_thresh_val = {RxFifoDepthW{1'b1}};
      end else begin
        rx_thresh_val = 1'b1 << uart_fifo_rxilvl;
      end
    end
    RxFifoDepthW-1: rx_thresh_val = RxFifoDepthW'(RxFifoDepth - 2);
  endcase

  event_rx_watermark = (rx_fifo_depth >= rx_thresh_val);
end

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    lsio_trigger_o <= 1'b0;
  end else begin
    // Simplified assertion for static data path enablement
    // TX/RX watermark logic handled within downstream DMA FSM
    lsio_trigger_o <= 1'b1;
  end
end

assign uart_rxto_en              = reg2hw.timeout_ctrl.en.q;
assign uart_rxto_val             = reg2hw.timeout_ctrl.val.q;
assign rx_fifo_depth_changed     = (rx_fifo_depth != rx_fifo_depth_prev_q);

assign rx_timeout_count_d =
            // don't count if timeout feature not enabled ;
            // will never reach timeout val + lower power
            (uart_rxto_en == 1'b0)              ? 24'd0 :
            // reset count if timeout interrupt is set
            event_rx_timeout                    ? 24'd0 :
            // reset count upon change in fifo level: covers both read and receiving a new byte
            rx_fifo_depth_changed               ? 24'd0 :
            // reset count if no bytes are pending
            (rx_fifo_depth == '0)               ? 24'd0 :
            // stop the count at timeout value (this will set the interrupt)
            //   Removed below line as when the timeout reaches the value,
            //   event occured, and timeout value reset to 0h.
            //(rx_timeout_count_q == uart_rxto_val) ? rx_timeout_count_q :
            // increment if at rx baud tick
            rx_tick_baud                        ? (rx_timeout_count_q + 24'd1) :
            rx_timeout_count_q;

assign event_rx_timeout = (rx_timeout_count_q == uart_rxto_val) & uart_rxto_en;

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    rx_timeout_count_q   <= 24'd0;
    rx_fifo_depth_prev_q <= '0;
  end else begin
    rx_timeout_count_q    <= rx_timeout_count_d;
    rx_fifo_depth_prev_q  <= rx_fifo_depth;
  end
end

  logic unused_reg;
  assign unused_reg = ^reg2hw.alert_test;

endmodule

module uart_rx (
  input           clk_i,
  input           rst_ni,

  input           rx_enable,
  input           tick_baud_x16,
  input           parity_enable,
  input           parity_odd,

  output logic    tick_baud,
  output logic    rx_valid,
  output [7:0]    rx_data,
  output logic    idle,
  output          frame_err,
  output          rx_parity_err,

  input           rx
);

  logic            rx_valid_q;
  logic   [10:0]   sreg_q, sreg_d;
  logic    [3:0]   bit_cnt_q, bit_cnt_d;
  logic    [3:0]   baud_div_q, baud_div_d;
  logic            tick_baud_d, tick_baud_q;
  logic            idle_d, idle_q;

  assign tick_baud = tick_baud_q;
  assign idle      = idle_q;

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    sreg_q      <= 11'h0;
    bit_cnt_q   <= 4'h0;
    baud_div_q  <= 4'h0;
    tick_baud_q <= 1'b0;
    idle_q      <= 1'b1;
  end else begin
    sreg_q      <= sreg_d;
    bit_cnt_q   <= bit_cnt_d;
    baud_div_q  <= baud_div_d;
    tick_baud_q <= tick_baud_d;
    idle_q      <= idle_d;
  end
end

always_comb begin
  if (!rx_enable) begin
    sreg_d      = 11'h0;
    bit_cnt_d   = 4'h0;
    baud_div_d  = 4'h0;
    tick_baud_d = 1'b0;
    idle_d      = 1'b1;
  end else begin
    tick_baud_d = 1'b0;
    sreg_d      = sreg_q;
    bit_cnt_d   = bit_cnt_q;
    baud_div_d  = baud_div_q;
    idle_d      = idle_q;
    if (tick_baud_x16) begin
      {tick_baud_d, baud_div_d} = {1'b0,baud_div_q} + 5'h1;
    end

    if (idle_q && !rx) begin
      // start of char, sample in the middle of the bit time
      baud_div_d  = 4'd8;
      tick_baud_d = 1'b0;
      bit_cnt_d   = (parity_enable ? 4'd11 : 4'd10);
      sreg_d      = 11'h0;
      idle_d      = 1'b0;
    end else if (!idle_q && tick_baud_q) begin
      if ((bit_cnt_q == (parity_enable ? 4'd11 : 4'd10)) && rx) begin
        // must have been a glitch on the input, start bit is not set
        // in the middle of the bit time, abort
        idle_d    = 1'b1;
        bit_cnt_d = 4'h0;
      end else begin
        sreg_d    = {rx, sreg_q[10:1]};
        bit_cnt_d = bit_cnt_q - 4'h1;
        idle_d    = (bit_cnt_q == 4'h1);
      end
    end
  end
end

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) rx_valid_q <= 1'b0;
  else         rx_valid_q <= tick_baud_q & (bit_cnt_q == 4'h1);

end

  assign rx_valid      = rx_valid_q;
  assign rx_data       = parity_enable ? sreg_q[8:1] : sreg_q[9:2];
  //    (rx_parity     = sreg_q[9])
  assign frame_err     = rx_valid_q & ~sreg_q[10];
  assign rx_parity_err = parity_enable & rx_valid_q &
                         (^{sreg_q[9:1],parity_odd});

endmodule

module uart_tx (
  input               clk_i,
  input               rst_ni,

  input               tx_enable,
  input               tick_baud_x16,
  input  logic        parity_enable,

  input               wr,
  input  logic        wr_parity,
  input   [7:0]       wr_data,
  output              idle,

  output logic        tx
);


  logic    [3:0] baud_div_q;
  logic          tick_baud_q;

  logic    [3:0] bit_cnt_q, bit_cnt_d;
  logic   [10:0] sreg_q, sreg_d;
  logic          tx_q, tx_d;

  assign tx = tx_q;

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    baud_div_q  <= 4'h0;
    tick_baud_q <= 1'b0;
  end else if (tick_baud_x16) begin
    {tick_baud_q, baud_div_q} <= {1'b0,baud_div_q} + 5'h1;
  end else begin
    tick_baud_q <= 1'b0;
  end
end

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    bit_cnt_q <= 4'h0;
    sreg_q    <= 11'h7ff;
    tx_q      <= 1'b1;
  end else begin
    bit_cnt_q <= bit_cnt_d;
    sreg_q    <= sreg_d;
    tx_q      <= tx_d;
  end
end

always_comb begin
  if (!tx_enable) begin
    bit_cnt_d = 4'h0;
    sreg_d    = 11'h7ff;
    tx_d      = 1'b1;
  end else begin
    bit_cnt_d = bit_cnt_q;
    sreg_d    = sreg_q;
    tx_d      = tx_q;
    if (wr) begin
      sreg_d    = {1'b1, (parity_enable ? wr_parity : 1'b1), wr_data, 1'b0};
      bit_cnt_d = (parity_enable ? 4'd11 : 4'd10);
    end else if (tick_baud_q && (bit_cnt_q != 4'h0)) begin
      sreg_d    = {1'b1, sreg_q[10:1]};
      tx_d      = sreg_q[0];
      bit_cnt_d = bit_cnt_q - 4'h1;
    end
  end
end
